const {Playtest,SLOTS,COST,project}=BonePick;
const $=id=>document.getElementById(id),canvas=$('field'),c=canvas.getContext('2d');
let g=new Playtest(),mode=null,hoverBranch=null,last=0,clock=0,uiAt=0,sound=false,audio=null,helpWasRunning=false;
const targetNodes=new Map(),laneNames=['Left','Center','Right'];
function oval(x,y,rx,ry,fill,stroke=null,w=2){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke();}}
function line(x,y,X,Y,color,width=3){c.beginPath();c.moveTo(x,y);c.lineTo(X,Y);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.stroke();}
function poly(points,color,stroke=null,w=2){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=w;c.stroke();}}
function leaf(x,y,s=1,a=0){c.save();c.translate(x,y);c.rotate(a);oval(0,0,7*s,14*s,'#83a955','#55723c',1);line(0,-10*s,0,11*s,'#52733c',s);c.restore();}
function groundRibbon(lane,from,to,color){const pts=[];for(let i=0;i<=20;i++){const d=from+(to-from)*i/20,p=project(lane,d);pts.push([p.x-(35+82*(1-d)),p.y]);}for(let i=20;i>=0;i--){const d=from+(to-from)*i/20,p=project(lane,d);pts.push([p.x+(35+82*(1-d)),p.y]);}poly(pts,color);}
function tree(x,y,s,shade){line(x,y,x+4*s,y-95*s,'#806849',14*s);line(x,y-40*s,x-30*s,y-80*s,'#806849',7*s);oval(x,y-125*s,45*s,43*s,shade);oval(x-30*s,y-100*s,40*s,35*s,shade);oval(x+34*s,y-100*s,37*s,34*s,shade);oval(x-15*s,y-143*s,25*s,20*s,'#91ae65');}
function background(){
 const sky=c.createLinearGradient(0,0,0,700);sky.addColorStop(0,'#d6e3ba');sky.addColorStop(.35,'#9cb879');sky.addColorStop(1,'#5c8146');c.fillStyle=sky;c.fillRect(0,0,1200,700);
 for(let i=0;i<20;i++){const x=i*70-40;tree(x,180+Math.sin(i)*12,.65+(i%3)*.1,'#77966c');}
 for(let i=0;i<12;i++){const x=i*120+((i%2)*20);if(x>430&&x<790)continue;tree(x,260+(i%3)*35,1.05+(i%2)*.3,'#527d4c');}
 for(let l=0;l<3;l++){groundRibbon(l,.0,1,'#b6a176');groundRibbon(l,0,1,'#c6b58c');for(let i=0;i<20;i++){const d=i/21,p=project(l,d);oval(p.x+Math.sin(i*5+l)*20*p.scale,p.y,3*p.scale,1.5*p.scale,'#9f936d77');}}
 for(let i=0;i<80;i++){const d=(i%20)/20,p=project(i%2?0:2,d),x=p.x+(i%2?1:-1)*(47+105*(1-d));line(x,p.y,x-4*p.scale,p.y-9*p.scale,'#466b39',2);line(x,p.y,x+3*p.scale,p.y-11*p.scale,'#799c4d',2);if(i%7===0){oval(x,p.y-10*p.scale,3*p.scale,3*p.scale,'#e9d9a1');oval(x,p.y-10*p.scale,p.scale,p.scale,'#b99a4e');}}
 // Low roots divide the lanes without blocking the view toward the forest.
 for(const sign of [-1,1]){c.beginPath();for(let i=0;i<=20;i++){const d=i/20,p=project(1,d),x=p.x+sign*(55+155*(1-d));if(i===0)c.moveTo(x,p.y);else c.lineTo(x,p.y);}c.strokeStyle='#8b8150';c.lineWidth=8;c.stroke();c.strokeStyle='#b3a671';c.lineWidth=3;c.stroke();}
 const range=hoverBranch?g.traps.find(t=>t.id===hoverBranch&&t.type==='branch'):null;
 if(range){groundRibbon(range.lane,Math.max(.03,range.d-.13),Math.min(1,range.d+.13),'#ffe58d77');const p=project(range.lane,range.d);c.textAlign='center';c.font='bold 13px system-ui';c.fillStyle='#574f28';c.fillText('SWEEP AREA',p.x,p.y+22*p.scale);}
 if(mode==='snare'||mode==='branch')for(let lane=0;lane<3;lane++)for(let slot=0;slot<4;slot++){if(g.traps.some(t=>t.type===mode&&t.lane===lane&&t.slot===slot))continue;const p=project(lane,SLOTS[slot]);oval(p.x,p.y,27*p.scale,11*p.scale,'#faedb444','#f2df9c',1.5);}
 for(let lane=0;lane<3;lane++){const warn=g.schedule.slice(g.spawnIndex).find(s=>s.lane===lane&&s.t-g.time<4);if(warn&&g.phase==='playing'){const p=project(lane,1);c.font='bold 22px Georgia';c.fillStyle='#ffe4a2';c.textAlign='center';c.fillText('!',p.x,p.y-28);}}
}
function skeleton(e){const p=project(e.lane,e.d),s=p.scale*(e.brute?1.35:1),walk=(e.held||e.stun)?0:Math.sin(clock*8)*3;c.save();c.translate(p.x,p.y);c.scale(s,s);oval(0,1,21,7,'#384e2a30');const bone=e.flash?'#fff7d7':'#e6dfc0',edge='#66694d';line(-7,-29,-11,-3+walk,edge,8);line(-7,-29,-11,-3+walk,bone,5);line(7,-29,12,-3-walk,edge,8);line(7,-29,12,-3-walk,bone,5);oval(-13,-2+walk,7,3,bone,edge,1);oval(14,-2-walk,7,3,bone,edge,1);line(0,-54,0,-25,edge,6);line(0,-54,0,-25,bone,3);for(let j=0;j<3;j++){c.beginPath();c.ellipse(0,-49+j*7,11-j,4,0,0,Math.PI);c.strokeStyle=edge;c.lineWidth=5;c.stroke();c.strokeStyle=bone;c.lineWidth=3;c.stroke();}line(-10,-52,-23,-32+walk,edge,6);line(-10,-52,-23,-32+walk,bone,3);line(10,-52,23,-33-walk,edge,6);line(10,-52,23,-33-walk,bone,3);oval(0,-70,19,18,bone,edge,2);poly([[-11,-62],[-10,-53],[10,-53],[12,-62]],bone,edge,1.5);oval(-7,-71,5,6,'#45513e');oval(8,-71,5,6,'#45513e');poly([[0,-65],[-3,-61],[3,-61]],'#677056');for(let x=-6;x<=6;x+=6)line(x,-58,x,-53,'#858967',1);if(e.brute){line(-22,-45,22,-45,'#ddd3ac',7);line(-22,-38,22,-38,'#ddd3ac',7);poly([[-18,-81],[-19,-94],[-7,-88],[1,-100],[9,-88],[19,-94],[19,-81]],'#c4a259',edge,2);c.fillStyle='#ae6c42';c.fillRect(-16,-110,32,4);c.fillStyle='#f2cd6d';c.fillRect(-16,-110,16*e.hp,4);}if(e.held>0){for(let k=0;k<3;k++){c.beginPath();c.ellipse(0,-5-k*5,19-k*2,6,0,0,Math.PI*2);c.strokeStyle='#577a3a';c.lineWidth=4;c.stroke();}leaf(14,-10,.55,.8);}c.restore();}
function drawTrap(t){const p=project(t.lane,t.d),s=p.scale;c.save();c.translate(p.x,p.y);c.scale(s,s);
 if(t.type==='snare'){oval(0,1,27,9,'#5b703e33');for(let j=0;j<3;j++){c.beginPath();c.ellipse(0,-j*3,23-j*4,8,0,0,Math.PI*2);c.strokeStyle=t.cooldown?'#8b8656':'#587b3f';c.lineWidth=5;c.stroke();}leaf(-19,-4,.65,-1);leaf(19,-5,.65,1);}
 else{const flip=t.lane===2?-1:1;c.scale(flip,1);oval(40,3,21,7,'#52693a33');line(45,0,44,-42,'#755b36',10);line(45,-40,24,-61,'#755b36',8);c.beginPath();c.moveTo(44,-36);c.quadraticCurveTo(7,-88,-35,-45);c.strokeStyle='#8a7044';c.lineWidth=8;c.stroke();line(-35,-45,42,0,'#7b9149',2);for(let j=0;j<4;j++)leaf(-29+j*17,-51-Math.sin(j*.8)*13,.55,j*.5);if(t.swing>0){c.save();c.globalAlpha=t.swing/.6;c.beginPath();c.ellipse(0,-25,65,23,-.2,0,Math.PI*2);c.strokeStyle='#fff1ae';c.lineWidth=8;c.stroke();line(40,-25,-48,-10,'#8d7141',10);c.restore();}oval(43,-57,8,8,t.cooldown>0?'#bb9361':'#efd16d','#6f633c',1);}
 c.restore();if(t.type==='branch'){c.textAlign='center';c.font=`bold ${Math.max(9,11*s)}px system-ui`;c.fillStyle=t.cooldown?'#5c5b3d':'#fff2b6';c.fillText(t.cooldown?Math.ceil(t.cooldown)+'s':'ARMED',p.x+45*s*(t.lane===2?-1:1),p.y-75*s);}}
function bones(p){const pos=project(p.lane,p.d),s=pos.scale;c.save();c.translate(pos.x,pos.y);c.scale(s,s);oval(0,0,22,8,'#655e3630');line(-18,-1,15,-12,'#e7dbb5',6);line(-16,-13,17,0,'#e7dbb5',6);oval(-15,-13,4,4,'#e7dbb5');oval(16,-1,4,4,'#e7dbb5');oval(0,-14,10,9,'#f0e4c1','#777454',1.5);oval(-3,-15,2.5,3,'#62664b');oval(4,-15,2.5,3,'#62664b');c.restore();}
function chipmunk(lane,d,load=0){const p=project(lane,d),s=p.scale*.85;c.save();c.translate(p.x+57*p.scale,p.y);c.scale(s,s);oval(18,-15,12,22,'#a76e3d','#5e4f30',2);oval(19,-18,6,17,'#d5ad73');oval(0,-13,15,20,'#b68048','#5e4f30',2);oval(-4,-12,9,16,'#e4c085');line(3,-28,5,-4,'#473f2d',5);line(7,-26,9,-6,'#f2d6a1',3);oval(-9,-43,7,8,'#aa7741');oval(8,-43,7,8,'#aa7741');oval(-2,-33,19,17,'#bd8951','#5e4f30',2);oval(-10,-28,9,8,'#e4bb7e');oval(8,-28,8,8,'#e4bb7e');oval(-7,-36,3,4,'#303c2b');oval(7,-36,3,4,'#303c2b');oval(0,-29,4,3,'#5a432e');line(0,-25,5,-23,'#5a432e',1.5);oval(-9,3,8,4,'#80552e');oval(9,3,8,4,'#80552e');poly([[-14,-20],[12,-20],[12,-14],[-14,-14]],'#5d8143');if(load){poly([[-23,-12],[13,-12],[9,5],[-19,5]],'#96a15c','#526f36',2);line(-18,-14,5,-17,'#eee4bd',5);oval(-4,-20,7,6,'#eee4bd');}c.restore();}
function doorway(){
 // The defended Oak surrounds the camera. No tree occupies the field itself.
 const left=[[0,0],[90,0],[77,120],[67,250],[80,430],[65,590],[98,700],[0,700]],right=left.map(([x,y])=>[1200-x,y]);poly(left,'#785534','#4e3e28',4);poly(right,'#785534','#4e3e28',4);for(let j=0;j<5;j++){line(12+j*12,0,18+j*9,700,j%2?'#9e7846':'#5f452d',4);line(1188-j*12,0,1182-j*9,700,j%2?'#9e7846':'#5f452d',4);}poly([[0,0],[1200,0],[1200,34],[1020,22],[900,34],[720,20],[500,29],[270,22],[90,45],[0,60]],'#795534','#4e3e28',3);
 for(let i=0;i<14;i++)leaf(86+i*80,18+(i%3)*8,.9,i*.7);
 poly([[0,669],[140,642],[238,658],[450,672],[748,668],[1050,648],[1200,660],[1200,700],[0,700]],'#8b6840','#5a472d',3);line(120,677,1050,682,'#bb955d',4);
 // Hanging lantern beside the doorway.
 line(59,50,59,105,'#494735',4);poly([[40,104],[77,104],[85,157],[33,157]],'#5d573a','#343e2c',3);poly([[47,111],[70,111],[74,149],[43,149]],'#e8be66');oval(58,135,8,13,'#fff0a5');
}
function render(){background();const things=[...g.traps.map(t=>({kind:'trap',item:t,d:t.d})),...g.piles.map(p=>({kind:'pile',item:p,d:p.d})),...g.enemies.map(e=>({kind:'enemy',item:e,d:e.d}))];if(g.crew.state!=='home')things.push({kind:'crew',item:g.crew,d:g.crew.d});things.sort((a,b)=>b.d-a.d);for(const t of things){if(t.kind==='trap')drawTrap(t.item);if(t.kind==='pile')bones(t.item);if(t.kind==='enemy')skeleton(t.item);if(t.kind==='crew')chipmunk(t.item.lane,t.item.d,t.item.load);}
 if(g.crew.state==='home')chipmunk(2,.03,0);for(const e of g.effects){const p=project(e.lane,e.d);c.globalAlpha=e.life/.7;for(let j=0;j<5;j++){const a=j*1.25,dist=(.7-e.life)*50;line(p.x+Math.cos(a)*dist,p.y-25+Math.sin(a)*dist,p.x+Math.cos(a)*(dist+8),p.y-25+Math.sin(a)*(dist+8),'#f4e7be',4);}c.globalAlpha=1;}doorway();}
function say(text){if(text)$('message').textContent=text;}
function beep(freq,duration=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),v=audio.createGain();o.frequency.value=freq;o.type='triangle';v.gain.setValueAtTime(.05,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function choose(value){mode=mode===value?null:value;hoverBranch=null;update();}
function target(key,label,p,w,h,kind,handler){let b=targetNodes.get(key);if(!b){b=document.createElement('button');b.className='target '+kind;b.dataset.key=key;$('targets').appendChild(b);targetNodes.set(key,b);b.onclick=()=>b.perform();b.onmouseenter=b.onfocus=()=>{hoverBranch=key.startsWith('t')?Number(key.slice(1)):null;};b.onmouseleave=b.onblur=()=>hoverBranch=null;}b.perform=handler;b.setAttribute('aria-label',label);b.title=label;b.style.left=p.x/12+'%';b.style.top=p.y/7+'%';b.style.width=w/12+'%';b.style.height=h/7+'%';b.textContent=kind==='pile'?'↟':kind==='slot'?'+':'';return key;}
function updateTargets(){const keep=new Set();if(['prep','playing'].includes(g.phase)){
 if(mode==='snare'||mode==='branch')for(let lane=0;lane<3;lane++)for(let slot=0;slot<4;slot++){if(g.traps.some(t=>t.type===mode&&t.lane===lane&&t.slot===slot))continue;const p=project(lane,SLOTS[slot]);keep.add(target('s'+lane+slot,`Build ${mode==='snare'?'Root Snare':'Branch Slapper'}: ${laneNames[lane]} lane, position ${slot+1}`,p,52*p.scale,28*p.scale,'slot',()=>{const err=g.place(mode,lane,slot);if(err)say(err);update();}));}
 for(const t of g.traps){const p=project(t.lane,t.d),s=p.scale;if(t.type==='branch')p.x+=43*s*(t.lane===2?-1:1);else if(mode!=='remove')continue;const label=mode==='remove'?`Remove ${t.type} in ${laneNames[t.lane]} lane`:`Inspect automatic branch: ${laneNames[t.lane]} lane, position ${t.slot+1}${t.cooldown>0?' (resetting)':' (armed)'}`;keep.add(target('t'+t.id,label,p,60*s,75*s,'trap',()=>{if(mode==='remove'){g.remove(t.id);say('Trap removed. Materials refunded.');}else{hoverBranch=t.id;say(t.cooldown>0?'This branch is resetting. It will re-arm automatically.':'Armed: this branch automatically hits skeletons in the gold sweep area.');}update();}));}
 for(const p of g.piles){const pos=project(p.lane,p.d);keep.add(target('p'+p.id,`Salvage ${p.value} materials: ${laneNames[p.lane]} lane`,pos,39*pos.scale,35*pos.scale,'pile',()=>{const err=g.send(p.id);if(err)say(err);update();}));}
 }for(const [key,node]of targetNodes)if(!keep.has(key)){node.remove();targetNodes.delete(key);}}
function update(){
 $('materials').textContent=g.materials;$('healthText').textContent=g.oak+'%';$('healthFill').style.width=g.oak+'%';$('recovered').textContent=g.stats.recovered;const left=Math.ceil(Math.max(0,60-g.time));$('timer').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');$('timeLabel').textContent=g.phase==='prep'?'PREPARE YOUR TRAPS':g.time>=60?'CLEAR THE REMAINING BONES':'WAVE TIME LEFT';$('startWave').classList.toggle('hidden',g.phase!=='prep');$('startWave').disabled=!$('intro').classList.contains('hidden');$('pause').disabled=!['playing','paused'].includes(g.phase);$('pause').textContent=g.phase==='paused'?'Resume':'Pause';$('pauseLabel').classList.toggle('hidden',g.phase!=='paused');$('snare').classList.toggle('selected',mode==='snare');$('branch').classList.toggle('selected',mode==='branch');$('modeHint').textContent=mode==='snare'?'Click a marked spot. Pairs well with a branch.':mode==='branch'?'Branches can share a position with a snare.':mode==='remove'?'Click a trap. Full refund in preparation; half during play.':'Choose a trap to show planting positions.';
 for(const b of document.querySelectorAll('[data-lane]')){const lane=Number(b.dataset.lane),ts=g.traps.filter(t=>t.type==='branch'&&t.lane===lane),ready=ts.some(t=>!t.cooldown);b.classList.toggle('armed',ready);b.querySelector('span').textContent=!ts.length?'No branch':ready?'Armed':Math.ceil(Math.min(...ts.map(t=>t.cooldown)))+'s to reset';}
 const crewLabels={home:'Home & ready',out:'Running to the bones',gather:'Gathering…',return:g.crew.load?'Bringing materials home':'Returning home',flee:'Retreating!'};$('crewText').innerHTML=crewLabels[g.crew.state]+'<small>'+(g.crew.state==='home'?'Click a bone pile to dispatch.':g.crew.load?g.crew.load+' materials in the basket.':'Keep an eye on nearby skeletons.')+'</small>';$('recall').disabled=g.crew.state==='home'||g.phase!=='playing';$('remove').textContent=mode==='remove'?'Cancel removal':'Remove trap';updateTargets();}
function togglePause(){if(!$('intro').classList.contains('hidden')||!$('helpPanel').classList.contains('hidden'))return;if(g.phase==='playing')g.phase='paused';else if(g.phase==='paused')g.phase='playing';update();}
function restart(){g=new Playtest();mode=null;hoverBranch=null;$('result').classList.add('hidden');$('helpPanel').classList.add('hidden');$('intro').classList.add('hidden');say('Prepare your traps. The center lane is already equipped.');update();}
function finish(){mode=null;const win=g.phase==='won';$('resultTitle').textContent=win?'Still standing. Still home.':'Let’s try that again.';$('resultText').textContent=win?'The wave is over. How did placing defenses and salvaging feel?':'The skeletons reached the Oak. Try pairing a snare and branch at the same position in each lane.';$('results').innerHTML=`<span><b>${g.stats.kills}</b><small>SKELETONS BUSTED</small></span><span><b>${g.stats.recovered}</b><small>MATERIALS SAVED</small></span><span><b>${g.stats.absorptions}</b><small>BONE BRUTES</small></span>`;$('resultTip').textContent=`${g.stats.swings} automatic strikes · ${g.stats.retreats} crew retreats. Replay to try different trap positions.`;$('result').classList.remove('hidden');update();}
$('begin').onclick=()=>{$('intro').classList.add('hidden');update();};$('snare').onclick=()=>choose('snare');$('branch').onclick=()=>choose('branch');$('startWave').onclick=()=>{mode=null;g.start();update();};$('pause').onclick=togglePause;$('restart').onclick=restart;$('again').onclick=restart;$('remove').onclick=()=>choose('remove');$('recall').onclick=()=>{if(g.phase==='playing')g.recall();};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';beep(440);};$('help').onclick=()=>{helpWasRunning=g.phase==='playing';if(helpWasRunning)g.phase='paused';$('helpPanel').classList.remove('hidden');update();};$('closeHelp').onclick=()=>{$('helpPanel').classList.add('hidden');if(helpWasRunning)g.phase='playing';helpWasRunning=false;update();};
window.addEventListener('keydown',e=>{if(e.repeat||!$('intro').classList.contains('hidden')||!$('result').classList.contains('hidden')||!$('helpPanel').classList.contains('hidden'))return;const k=e.key.toLowerCase();if(k===' '){e.preventDefault();togglePause();}if(k==='1')choose('snare');if(k==='2')choose('branch');if(k==='escape'){mode=null;hoverBranch=null;update();}if(k==='r'&&g.phase==='playing')g.recall();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&g.phase==='playing'){g.phase='paused';update();}});
function frame(now){const dt=Math.min(.05,(now-last)/1000||0);last=now;clock+=dt;g.step(dt);while(g.events.length){const e=g.events.shift();say(e.text);if(e.type==='swing')beep(150,.15);if(e.type==='salvaged')beep(650);if(e.type==='damage'||e.type==='absorb')beep(100,.2);if(e.type==='won'||e.type==='lost')finish();}render();if(clock-uiAt>.1){update();uiAt=clock;}requestAnimationFrame(frame);}update();requestAnimationFrame(frame);
